static BreakerRating Rating(string id,double current,double capacity){return new BreakerRating{Manufacturer="QA sintético",Reference=id,VoltageV=400,FrequencyHz=60,Poles=PoleLayout.ThreePole,Metric=BreakingMetric.Icu,RatedA=current,CapacityKA=capacity,I2A=current*1.45,Source="Fonte de ensaio Ω",DataVersion="2026.10",Standard="Classificação sintética QA",Sheet="QA 400V/60Hz/3P"};}
static Project Fixture(){var p=new Project();p.Source.LineVoltage=400;p.Source.ShortCircuitKA=6;var a=new Board{Id="Q1",Voltage=400};var b=new Board{Id="Q2",Voltage=400};var up=new Circuit{Id="UP",ChildBoardId="Q2",Phases=PhaseMode.Trifasico,PhaseLabel="ABC",Voltage=400,PowerFactor=1,BreakerA=63,CableMm2=50,LengthM=10};up.Cable.AmpacityA=100;up.Cable.ResistanceOhmKm=.1;up.Cable.ReactanceOhmKm=0;var down=new Circuit{Id="DOWN",Phases=PhaseMode.Trifasico,PhaseLabel="ABC",Voltage=400,PowerKw=8*Math.Sqrt(3),PowerFactor=1,BreakerA=25,CableMm2=10,LengthM=10};down.Cable.AmpacityA=32;a.Circuits.Add(up);b.Circuits.Add(down);p.Boards.Add(a);p.Boards.Add(b);BreakerSelection.Apply(p,up,Rating("UP63",63,25),PoleLayout.ThreePole,BreakingMetric.Icu);BreakerSelection.Apply(p,down,Rating("DOWN25",25,10),PoleLayout.ThreePole,BreakingMetric.Icu);return p;}
static Circuit Down(Project p){return p.Boards[1].Circuits[0];}static CoordinationRecord Record(Project p,CoordinationKind kind){var r=Coordination.Template(p,Down(p),kind);r.MinimumCurrentA=100;r.LimitKA=10;r.Issuer="Emissor sintético QA";r.Document="Ensaio sintético; \"A\" Ω";r.Page="QA-1";r.DataVersion="2026.10";r.Scope="Intervalo de curto de ensaio; não é tabela certificada real";return r;}
static CoordinationEvaluation Eval(Project p,CoordinationRecord r){return Coordination.Evaluate(p,Engineering.Analyze(p),Down(p),r);}
[STAThread]public static int Main(){string dir=Path.Combine(Path.GetTempPath(),"coordination-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{var p=Fixture();var down=Down(p);var up=Coordination.Upstream(p,down);Check(up.Id=="UP","upstream inferred from actual board feeder");Check(Coordination.Upstream(p,up)==null,"root does not invent an upstream breaker");Check(Eval(p,null).Status=="Indeterminado","missing pair evidence stays indeterminate");var template=Coordination.Template(p,down,CoordinationKind.Selectivity);Check(Eval(p,template).Status=="Indeterminado"&&!Eval(p,template).ContextMatches,"unfilled template cannot become evidence");var record=Record(p,CoordinationKind.Selectivity);var result=Eval(p,record);Check(result.Status=="Compatível com tabela declarada"&&result.ContextMatches,"exact pair within declared range");Check(result.Detail.Contains("nominal")&&result.Detail.Contains("Autenticidade")&&result.Detail.Contains(record.Document),"result explains scope and responsibility for source verification");double ik=result.CurrentKA.Value;record.LimitKA=ik;Check(Eval(p,record).Status=="Compatível com tabela declarada","inclusive upper boundary");record.MinimumCurrentA=ik*1000;Check(Eval(p,record).Status=="Compatível com tabela declarada","inclusive lower boundary");record.MinimumCurrentA=0;record.LimitKA=ik*.99;Check(Eval(p,record).Status=="Indeterminado","outside upper bound never extrapolates selectivity");record.LimitKA=10;record.MinimumCurrentA=ik*1000+1;Check(Eval(p,record).Status=="Indeterminado","below tested range never extrapolates");record=Record(p,CoordinationKind.Selectivity);record.SystemVoltageV=415;Check(!Eval(p,record).ContextMatches,"higher test voltage not extrapolated");record=Record(p,CoordinationKind.Selectivity);record.FrequencyHz=50;Check(!Eval(p,record).ContextMatches,"frequency must match");record=Record(p,CoordinationKind.Selectivity);string signature=record.UpstreamConfiguration;record.UpstreamConfiguration=record.Down