up.Protection.MagneticTripA=300;Check(!Eval(p,record).ContextMatches,"magnetic setting change invalidates association");up.Protection.MagneticTripA=0;down.Protection.DisconnectSeconds=.2;Check(!Eval(p,record).ContextMatches,"time setting change invalidates association");down.Protection.DisconnectSeconds=0;down.CurveStudy=new CurveStudyData{Downstream=ManufacturerCurve.Parse("CurrentA;MinSeconds;MaxSeconds\n10;1;2\n100;.1;.2","QA curve")};Check(!Eval(p,record).ContextMatches,"curve change invalidates association");down.CurveStudy=null;Check(Eval(p,record).ContextMatches,"restoring original configuration restores exact match");
