var originalCapacity=up.Protection.BreakingCapacityKA;up.Protection.BreakingCapacityKA=3;up.Protection.BreakerSnapshot.Rating.CapacityKA=3;Check(Eval(p,Record(p,CoordinationKind.Selectivity)).Status=="Indeterminado","upstream must withstand its own available fault");up.Protection.BreakingCapacityKA=originalCapacity;up.Protection.BreakerSnapshot.Rating.CapacityKA=originalCapacity;
Coordination.Attach(p,down,record);Check(down.SelectivityEvidence.Record!=record,"attached evidence is independent copy");record.Document="Changed outside project";Check(down.SelectivityEvidence.Record.Document.Contains("sintético"),"library changes cannot alter project snapshot");Check(Engineering.Analyze(p).Checks.Any(x=>x.Rule=="Seletividade por tabela de par"&&x.Status=="Compatível com tabela declarada"),"linked evidence visible in complete study");var invalid=Record(p,CoordinationKind.Selectivity);invalid.DownstreamConfiguration=new string('a',64);var binding=down.SelectivityEvidence;Reject(delegate{Coordination.Attach(p,down,invalid);},"incompatible evidence cannot be attached");Check(Object.ReferenceEquals(binding,down.SelectivityEvidence),"failed attachment preserves previous evidence");
var duplicate=ProjectEditing.DuplicateCircuit(p,p.Boards[1],down);Check(duplicate.SelectivityEvidence!=down.SelectivityEvidence&&duplicate.SelectivityEvidence.Record!=down.SelectivityEvidence.Record,"duplicate owns independent evidence");Check(Coordination.EvaluateBinding(p,Engineering.Analyze(p),duplicate,CoordinationKind.Selectivity).Status=="Indeterminado","duplicated circuit must explicitly rebind association");p.Boards[1].Circuits.Remove(duplicate);
var low=Rating("DOWN25-low",25,3);Reject(delegate{BreakerSelection.Apply(p,down,low,PoleLayout.ThreePole,BreakingMetric.Icu);},"normal breaker application still rejects inadequate individual interruption");BreakerSelection.ApplyForCoordinationStudy(p,down,low,PoleLayout.ThreePole,BreakingMetric.Icu);Check(down.Protection.BreakingCapacityKA==3&&Engineering.Analyze(p).Checks.Any(x=>x.Rule=="Capacidade de interrupção"&&x.Status=="Falha"),"explicit coordination preselection retains individual failure");Check(Coordination.EvaluateBinding(p,Engineering.Analyze(p),down,CoordinationKind.Selectivity).Status=="Indeterminado","new downstream device invalidates prior pair");var backup=Record(p,CoordinationKind.Backup);Check(Eval(p,backup).Status=="Compatível com tabela declarada","backup uses pair limit despite lower individual downstream rating");Coordination.Attach(p,down,backup);Check(Engineering.Analyze(p).Checks.Any(x=>x.Rule=="Backup por tabela de par"&&x.Status=="Compatível com tabela declarada"),"backup nominal comparison visible separately");Check(Eval(p,Record(p,CoordinationKind.Selectivity)).Status=="Indeterminado","selectivity cannot assume adequacy from uncombined backup evidence");backup.LimitKA=ik*.99;Check(Eval(p,backup).Status=="Indeterminado","insufficient declared backup limit cannot approve");backup=down.BackupEvidence.Record.Copy();var bad=Rating("BAD",19,3);Reject(delegate{BreakerSelection.ApplyForCoordinationStudy(p,down,bad,PoleLayout.ThreePole,BreakingMetric.Icu);},"coordination study cannot bypass overload failure");bad=Rating("BAD",33,3);Reject(delegate{BreakerSelection.ApplyForCoordinationStudy(p,down,bad,PoleLayout.ThreePole,BreakingMetric.Icu);},"coordination study cannot bypass Iz failure");bad=Rating("BAD",25,3);bad.VoltageV=230;Reject(delegate{BreakerSelection.ApplyForCoordinationStudy(p,down,bad,PoleLayout.ThreePole,BreakingMetric.Icu);},"coordination study cannot bypass voltage failure");
string csv=Path.Combine(dir,"pairs.csv");Coordination.Export(new[]{backup},csv);var imported=Coordination.Import(csv);Check(imported.Count==1&&imported[0].Document==backup.Document&&imported[0].DownstreamConfiguration==backup.DownstreamConfiguration,"CSV Unicode quotes and configurations roundtrip");Coordination.Export(new CoordinationRecord[0],Path.Combine(dir,"empty.csv"));Check(Coordination.Import(Path.Combine(dir,"empty.csv")).Count==0,"empty template imports");Coordination.Export(new[]{backup},csv);var before=File.ReadAllBytes(csv);var bak=File.ReadAllBytes(csv+".bak");invalid=backup.Copy();invalid.Document="";Reject(delegate{Coordination.Export(new[]{invalid},csv);},"missing document rejected");Check(File.ReadAllBytes(csv).SequenceEqual(before)&&File.ReadAllBytes(csv+".bak").SequenceEqual(bak),"failed export preserves active data and backup");Reject(delegate{Coordination.Export(new[]{backup,backup.Copy()},csv);},"duplicate pair condition rejected");foreach(double x in new[]{0,-1,double.NaN,double.PositiveInfinity}){invalid=backup.Copy();invalid.LimitKA=x;Reject(invalid.Validate,"invalid current limit rejected");}invalid=backup.Copy();invalid.MinimumCurrentA=invalid.LimitKA*1000+1;Reject(invalid.Validate,"inverted current range rejected");invalid=backup.Copy();invalid.UpstreamConfiguration="bad";Reject(invalid.Validate,"malformed configuration rejected");invalid=backup.Copy();invalid.Basis=(CoordinationBasis)99;Reject(invalid.Validate,"unknown evidence basis rejected");string large=Path.Combine(dir,"large.csv");using(var stream=File.Create(large))stream.SetLength(32L*1024*1024+1);Reject(delegate{Coordination.Import(large);},"oversize import rejected");var huge=new List<CoordinationRecord>();string big=new string('x',2000);for(int i=0;i<6000;i++){var row=backup.Copy();row.FrequencyHz=1+i*.01;row.UpstreamReference=row.DownstreamReference=row.Scope=big;huge.Add(row);}Reject(delegate{Coordination.Export(huge,csv);},"oversize export rejected");Check(File.ReadAllBytes(csv).SequenceEqual(before)&&File.ReadAllBytes(csv+".bak").SequenceEqual(bak)&&Directory.GetFiles(dir,"*.tmp").Length==0,"overflow preserves files and removes temporary data");
string project=Path.Combine(dir,"project.circuito");p.Save(project);string saved=File.ReadAllText(project);Check(saved.Contains("coordination-tables-v1")&&saved.Contains("\"FileVersion\":4"),"new association capability protects format");var loaded=Project.Load(project);Check(Down(loaded).BackupEvidence.Record.Document==backup.Document,"evidence survives reopen");Check(Coordination.EvaluateBinding(loaded,Engineering.Analyze(loaded),Down(loaded),CoordinationKind.Backup).Status=="Compatível com tabela declarada","reopened association reproducible");Check(EngineeringReport.Memory(p,Engineering.Analyze(p))==EngineeringReport.Memory(loaded,Engineering.Analyze(loaded)),"full report with associations reproduces after reopen");Check(EngineeringReport.Memory(p,Engineering.Analyze(p)).Contains(backup.Document),"memory preserves evidence and result");File.WriteAllText(project,saved.Replace(Coordination.EngineId,"future-pair-engine"));Reject(delegate{Project.Load(project);},"unknown evaluator revision rejected");File.WriteAllText(project,saved);string previous=Environment.GetEnvironmentVariable("CIRCUITO_QA_PREVIOUS_EXE");if(!String.IsNullOrWhiteSpace(previous)){var assembly=Assembly.LoadFile(Path.GetFullPath(previous));bool rejected=false;try{assembly.GetType("CircuitoStudio.Project").GetMethod("Load").Invoke(null,new object[]{project});}catch(TargetInvocationException ex){rejected=ex.InnerException is InvalidDataException;}Check(rejected,"actual prior executable rejects unknown coordination capability");}
string artifacts=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-coordenacao");Directory.CreateDirectory(artifacts);p.Save(Path.Combine(artifacts,"origem.circuito"));Coordination.Export(new[]{backup},Path.Combine(artifacts,"pares.csv"));File.WriteAllText(Path.Combine(artifacts,"resultado.txt"),Coordination.EvaluateBinding(p,Engineering.Analyze(p),down,CoordinationKind.Backup).Detail,new UTF8Encoding(true));File.WriteAllText(Path.Combine(artifacts,"ik.txt"),ik.ToString("R",System.Globalization.CultureInfo.InvariantCulture));using(var form=new CoordinationForm(p,down,csv)){form.CreateControl();var kind=(ComboBox)typeof(CoordinationForm).GetField("kind",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);kind.SelectedIndex=1;Check(!form.Changed,"opening comparison does not change binding");if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(10,10);form.Show();Application.DoEvents();using(var bitmap=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bitmap.Save(Path.Combine(artifacts,"coordenacao.png"));}form.Hide();}}
Console.WriteLine("PASS: "+n+" coordination assertions");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{Directory.Delete(dir,true);}}
